(()=>{'use strict';
const people=JSON.parse(document.querySelector('#map-data').textContent),search=document.querySelector('#map-search'),setting=document.querySelector('#map-setting'),status=document.querySelector('#map-status');
let map,layer;
const placements=new Map(),regions=new Map();
for(const p of people){const r=p.regions[0];if(r){if(!regions.has(r.label))regions.set(r.label,[]);regions.get(r.label).push(p);}}
for(const group of regions.values()){group.sort((a,b)=>a.slug.localeCompare(b.slug));group.forEach((p,i)=>{const r=p.regions[0],angle=i*2.399963229728653,radius=group.length===1?0:0.65*Math.sqrt(i+1);placements.set(p.slug,[r.lat+Math.sin(angle)*radius,r.lng+Math.cos(angle)*radius/Math.cos(r.lat*Math.PI/180)]);});}
const nugget='<svg aria-hidden="true" viewBox="0 0 32 32"><path d="M6 10 15 4 24 7 28 19 21 27 9 26 3 18Z" fill="#dba12c" stroke="#76501c" stroke-width="1.5"/><path d="m6 10 9-6 3 10-9 5Z" fill="#ffe18a"/><path d="m18 14 6-7 4 12-7 8Z" fill="#bd7d1c"/><path d="m9 19 9-5 3 13-12-1Z" fill="#edbd4b"/><path d="m10 10 4-2" stroke="#fff2b0" stroke-width="2" stroke-linecap="round"/></svg>';
if(window.L){map=L.map('creator-map',{scrollWheelZoom:false,maxZoom:12}).setView([44,-100],3);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:12,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);layer=L.layerGroup().addTo(map);}else document.querySelector('#creator-map').textContent='Map could not load. You can still explore the creator list below.';
function update(){const q=search.value.trim().toLowerCase(),kind=setting.value;const visible=people.filter(p=>(p.name+' '+p.introduction+' '+p.regions.map(r=>r.label).join(' ')).toLowerCase().includes(q)&&(!kind||(kind==='unknown'?!p.settings.length:p.settings.includes(kind))));const slugs=new Set(visible.map(p=>p.slug));document.querySelectorAll('.map-person').forEach(c=>c.hidden=!slugs.has(c.dataset.slug));const located=visible.filter(p=>p.regions.length).length;status.textContent=visible.length+' creator'+(visible.length===1?'':'s')+' · '+located+' nuggets · '+(visible.length-located)+' without a mapped region (see list)' ;if(!map)return;layer.clearLayers();for(const p of visible){if(!placements.has(p.slug))continue;const content=document.createElement('div'),heading=document.createElement('strong'),note=document.createElement('p'),intro=document.createElement('p'),link=document.createElement('a');heading.textContent=p.name;intro.textContent=p.introduction;note.textContent=p.regions.map(r=>r.label).join(' · ')+' — approximate regional placement, not a prospecting site.';link.href=p.profileUrl||'/prospectors/'+encodeURIComponent(p.slug)+'/';link.textContent='View creator profile →';content.append(heading,intro,note,link);L.marker(placements.get(p.slug),{title:p.name+' — '+p.regions[0].label,alt:p.name,icon:L.divIcon({className:'map-nugget',html:nugget,iconSize:[26,26],iconAnchor:[13,13]})}).bindTooltip(p.name,{direction:'top'}).bindPopup(content).addTo(layer);}}
search.addEventListener('input',update);setting.addEventListener('change',update);document.querySelector('#map-reset').addEventListener('click',()=>{search.value='';setting.value='';map?.setView([44,-100],3);update();});update();})();